ENR[7] = {
 'Développement comme extension des capabilités': {
  'af': "Sen soutient que le développement ne doit pas être mesuré par le revenu mais par l'élargissement des libertés réelles, c'est-à-dire par l'ensemble des vies qu'une personne est effectivement en mesure de mener. Sa thèse repose sur une distinction en trois termes. Les ressources — un revenu, un bien — ne sont que des moyens. Les fonctionnements sont ce qu'une personne parvient effectivement à être ou à faire : être nourrie, en bonne santé, instruite, participer à la vie publique. Les capabilités désignent l'ensemble des combinaisons de fonctionnements accessibles, c'est-à-dire la liberté réelle de choisir sa vie. L'apport décisif tient au taux de conversion des ressources en fonctionnements, qui varie fortement d'une personne à l'autre selon des facteurs personnels, sociaux et environnementaux : à revenu identique, une personne handicapée, discriminée ou privée d'infrastructures atteint beaucoup moins. Évaluer le développement par le seul revenu revient donc à ignorer ce qui le rend utile.",
  'po': "Dans le chapitre, cette thèse fournit le fondement théorique de la distinction entre croissance et développement et justifie le recours à des indicateurs composites comme l'IDH. Elle commande la structure de l'ensemble du chapitre, puisqu'elle impose d'examiner successivement la santé, l'éducation, les inégalités et les libertés, et non seulement la production.",
  'co': "Amartya Sen définit le développement comme l'extension des capabilités, c'est-à-dire des libertés réelles de choisir sa vie : le revenu n'étant qu'un moyen dont le taux de conversion en accomplissements varie selon les personnes, le développement ne peut se mesurer par le seul produit par habitant.",
 },
 'Étapes de la croissance et take-off appliqués au développement': {
  'af': "Appliquée au développement, la thèse de Rostow soutient que tout pays peut se développer en franchissant une même séquence d'étapes, et que le sous-développement constitue donc un retard et non une situation produite. L'implication est forte : si le blocage est un simple défaut d'accumulation, il suffit de porter le taux d'investissement au-delà du seuil critique et de faire émerger des secteurs entraînants pour que la croissance devienne auto-entretenue. De là découlent les politiques d'aide massive à l'investissement et les grands projets d'infrastructure des années 1960, directement inspirés de cette lecture. La faiblesse de la thèse réside dans son postulat d'autonomie : la trajectoire d'un pays est supposée indépendante de sa position dans le système économique mondial, comme si chaque nation parcourait seule son chemin. C'est précisément ce postulat que les analyses structuralistes et dépendantistes contesteront.",
  'po': "Dans le chapitre, cette thèse constitue la première grande théorie du développement et sert de référence à réfuter : c'est en montrant que le sous-développement est produit par des relations internationales, et non seulement par un retard interne, que les auteurs suivants construisent leur argumentation. Elle fournit donc l'ossature du débat.",
  'co': "Pour Rostow, le sous-développement est un retard que le franchissement d'un seuil d'investissement et l'émergence de secteurs moteurs permettent de combler : cette lecture suppose cependant que la trajectoire de chaque pays soit indépendante de sa position dans le système économique mondial.",
 },
 "Dualisme et transfert de main-d'œuvre": {
  'af': "Lewis soutient que le développement d'une économie pauvre repose sur le transfert de main-d'œuvre d'un secteur traditionnel, où la productivité marginale du travail est quasi nulle, vers un secteur moderne où elle est élevée. La thèse décrit une économie dualiste. Dans le secteur traditionnel, souvent agricole et familial, la main-d'œuvre est surabondante au point que retirer un travailleur ne réduit presque pas la production : il existe un sous-emploi déguisé. Le secteur moderne peut donc recruter en masse à un salaire à peine supérieur au revenu de subsistance, ce qui lui garantit un profit élevé, donc une capacité d'autofinancement et d'expansion. Le processus se poursuit tant que subsiste ce réservoir, d'où l'expression d'offre illimitée de travail. Lewis identifie toutefois un terme : lorsque le réservoir s'épuise, les salaires industriels montent — c'est le point de retournement — et la croissance doit alors reposer sur la productivité et non plus sur le transfert.",
  'po': "Dans le chapitre, ce modèle fournit le mécanisme sectoriel concret par lequel un pays s'industrialise, là où Rostow se contentait de décrire un seuil. Il explique à la fois la rapidité des rattrapages asiatiques et leur essoufflement, et il relie le développement à la question du partage de la valeur ajoutée, puisque le profit élevé du secteur moderne repose sur la faiblesse du salaire.",
  'co': "Arthur Lewis explique le développement par le transfert de main-d'œuvre d'un secteur traditionnel à productivité marginale quasi nulle vers un secteur moderne : l'offre illimitée de travail y maintient les salaires bas et le profit élevé, jusqu'au point de retournement où l'épuisement du réservoir fait monter les salaires.",
 },
 'Cercle vicieux de la pauvreté': {
  'af': "Nurkse soutient que la pauvreté s'auto-entretient par un enchaînement circulaire que le marché seul ne peut pas rompre. Le cercle se referme des deux côtés du marché. Du côté de l'offre, un revenu de subsistance ne laisse aucune marge d'épargne, donc aucun financement de l'investissement, donc aucune hausse de la productivité, donc aucun revenu supplémentaire. Du côté de la demande, l'étroitesse du marché intérieur dissuade d'investir, puisque aucune activité ne peut atteindre une taille rentable. La thèse a une conséquence stratégique décisive, qui la distingue d'une simple description : une impulsion marginale est inefficace, car chaque élément reste bloqué par les autres. Il faut une poussée simultanée et de grande ampleur portant sur plusieurs secteurs complémentaires, ce qui justifie une coordination publique ou un apport extérieur massif, aucun investisseur isolé n'ayant intérêt à agir le premier.",
  'po': "Dans le chapitre, cette analyse explique la persistance du sous-développement par un mécanisme économique interne, et fonde les politiques de grands programmes coordonnés. Elle fournit le contrepoint à l'approche expérimentale de Banerjee et Duflo, qui conteste précisément l'existence d'un blocage global au profit de contraintes localisées.",
  'co': "Ragnar Nurkse décrit un cercle vicieux de la pauvreté : le faible revenu limite l'épargne donc l'investissement, tandis que l'étroitesse du marché intérieur décourage toute implantation rentable, de sorte que seule une poussée coordonnée sur plusieurs secteurs complémentaires peut rompre l'enchaînement.",
 },
 'Substituts institutionnels au service du rattrapage': {
  'af': "Gerschenkron soutient qu'un pays en retard peut rattraper son avance technologique à condition de se doter d'institutions capables de mobiliser le capital que son marché financier ne fournit pas. La thèse repose sur une tension. D'un côté, le retardataire bénéficie d'un avantage : il accède d'emblée aux techniques les plus avancées sans supporter le coût de leur mise au point. De l'autre, ces techniques exigent une mise de fonds initiale sans commune mesure avec celle du pionnier, qui avait pu accumuler progressivement. Il faut donc une institution de substitution capable d'agréger l'épargne dispersée et d'accepter un horizon long : les grandes banques universelles en Allemagne, l'État en Russie. Gerschenkron en tire une proposition de portée générale : l'institution appropriée dépend du degré de retard, ce qui exclut la transposition d'un modèle unique de développement.",
  'po': "Dans le chapitre, cette thèse constitue l'une des réfutations les plus solides du modèle linéaire de Rostow et fournit un argument historique en faveur d'un rôle actif de l'État ou des banques dans le rattrapage. Elle prépare l'analyse des politiques industrielles asiatiques étudiées en deuxième année.",
  'co': "Alexander Gerschenkron montre que le rattrapage exige des institutions de substitution — grandes banques en Allemagne, État en Russie — capables de mobiliser des capitaux que le marché local ne fournit pas, et que l'institution appropriée dépend du degré de retard initial.",
 },
 "Centre-périphérie et détérioration des termes de l'échange": {
  'af': "Prebisch soutient que l'insertion dans le commerce mondial reproduit la dépendance des pays spécialisés dans les produits primaires au lieu de la réduire, parce que leurs termes de l'échange se dégradent tendanciellement. La thèse repose sur une asymétrie systématique entre centre et périphérie, qui joue des deux côtés du marché. Du côté de la demande, l'élasticité-revenu des produits primaires est faible, de sorte que la croissance mondiale accroît davantage la demande de produits manufacturés que celle de matières premières. Du côté de l'offre, les gains de productivité ne sont pas répartis de la même façon : au centre, des marchés concentrés et des salariés organisés permettent de les capter sous forme de hausses de revenus ; à la périphérie, la concurrence entre producteurs atomisés les transmet en baisses de prix. Il faut donc exporter toujours plus de produits primaires pour importer la même quantité de biens d'équipement.",
  'po': "Dans le chapitre, cette analyse constitue la rupture théorique majeure avec la lecture ricardienne de la spécialisation : elle établit que l'échange peut être mutuellement avantageux à un instant donné et cumulativement défavorable dans la durée. Elle fonde la stratégie d'industrialisation par substitution aux importations, examinée ensuite.",
  'co': "Raúl Prebisch montre que les termes de l'échange des exportateurs de produits primaires se dégradent tendanciellement : la faible élasticité-revenu de la demande et la transmission des gains de productivité en baisses de prix réduisent leur capacité d'importation et reproduisent leur dépendance.",
 },
 'Thèse Prebisch-Singer': {
  'af': "Singer établit que la détérioration des termes de l'échange des exportateurs de produits primaires constitue une tendance statistique de longue période et non une conjoncture défavorable, et il en précise le mécanisme le plus contre-intuitif. Son apport propre tient à ce qu'il advient du progrès technique réalisé dans la périphérie : lorsqu'un pays exportateur améliore ses rendements, l'accroissement de l'offre fait baisser le prix mondial, de sorte que le gain de productivité bénéficie au consommateur étranger et non au producteur. Le progrès technique, qui dans le centre élève les revenus, se traduit dans la périphérie par un transfert de valeur vers l'extérieur. Il en résulte une conclusion sévère pour les politiques fondées sur la seule modernisation agricole : améliorer la productivité d'une spécialisation primaire ne suffit pas à sortir de la dépendance, et peut même l'aggraver.",
  'po': "Dans le chapitre, cette précision renforce l'argumentation structuraliste en montrant que le problème n'est pas l'insuffisance de productivité mais la structure de la spécialisation. Elle justifie que la stratégie de développement porte sur le changement de spécialisation et non sur l'amélioration de l'existante.",
  'co': "Hans Singer précise la thèse Prebisch-Singer : lorsque le progrès technique a lieu dans la périphérie, il fait baisser le prix mondial du produit exporté et bénéficie donc au consommateur du centre, de sorte que moderniser une spécialisation primaire ne réduit pas la dépendance.",
 },
 'Échange inégal et dépendance périphérique': {
  'af': "Amin soutient que le sous-développement n'est pas un retard mais un produit : l'insertion dominée dans le système mondial façonne des économies dont la structure interne est déformée au service de l'accumulation réalisée ailleurs. La thèse décrit une économie extravertie, dont les traits sont cohérents entre eux. Les secteurs exportateurs y sont modernes mais déconnectés du reste du territoire, sans effets d'entraînement internes. La demande intérieure solvable est trop étroite pour soutenir une industrie nationale, puisque les revenus se concentrent dans une minorité dont la consommation est importée. Les élites locales tirent leur revenu de l'exportation et n'ont donc aucun intérêt à l'intégration du marché intérieur. Les circuits d'accumulation se bouclent à l'extérieur. Amin en déduit une prescription radicale : le développement suppose une déconnexion partielle et une réorientation de la production vers les besoins internes.",
  'po': "Dans le chapitre, cette thèse pousse à son terme la critique structuraliste en faisant du sous-développement un rapport et non un état : il suppose un ailleurs qui s'enrichit du même mouvement. Elle fournit la position la plus radicale du débat sur les stratégies de développement, à confronter au succès ultérieur des stratégies asiatiques tournées vers l'exportation.",
  'co': "Samir Amin soutient que le sous-développement est produit par l'insertion dominée dans le système mondial : l'économie extravertie juxtapose un secteur exportateur moderne sans effets d'entraînement et un marché intérieur étroit, ce qui le conduit à prôner une déconnexion partielle.",
 },
 'Échange inégal': {
  'af': "Emmanuel soutient que le commerce international transfère de la valeur de la périphérie vers le centre, parce que les écarts internationaux de salaires y sont beaucoup plus grands que les écarts de productivité. La thèse se situe dans le cadre de la valeur-travail : si deux pays échangent des marchandises aux prix du marché mondial alors que les salaires sont très inférieurs dans l'un d'eux, la quantité de travail incorporée dans les biens échangés n'est pas équivalente, et la périphérie cède davantage d'heures de travail qu'elle n'en reçoit. Le point remarquable est que ce mécanisme ne suppose aucune tricherie commerciale ni aucun pouvoir de marché : il résulte de la seule asymétrie de mobilité, les marchandises et les capitaux circulant librement alors que le travail reste immobile. Le commerce peut donc être formellement libre et équitable et substantiellement inégal.",
  'po': "Dans le chapitre, cette analyse fournit le fondement théorique le plus rigoureux des thèses dépendantistes et prolonge Marx en l'appliquant aux relations internationales. Elle permet de distinguer soigneusement l'égalité formelle de l'échange et son contenu réel, distinction qui servira plus loin dans l'analyse du dumping social.",
  'co': "Arghiri Emmanuel montre que l'échange international est inégal parce que les écarts de salaires excèdent les écarts de productivité : la périphérie cède davantage d'heures de travail qu'elle n'en reçoit, sans qu'aucune entorse aux règles du commerce ne soit nécessaire.",
 },
 'Nuancer le lien entre ouverture et développement': {
  'af': "Bairoch soutient que l'histoire économique ne valide ni la thèse selon laquelle le libre-échange produit le développement, ni la thèse inverse, et que les trajectoires réelles combinent protection, marché intérieur et ouverture selon des dosages variables. La démarche consiste à confronter les données longues aux récits dominants, et c'est la rigueur de cette confrontation qui fait la force de la thèse. Bairoch relève que les grandes puissances industrielles du XIXᵉ siècle se sont développées derrière des tarifs élevés, que certains épisodes de libéralisation ont coïncidé avec des ralentissements, mais aussi que des pays fortement protégés ont stagné. Sa conclusion n'est donc pas l'inversion du dogme libre-échangiste mais le refus d'une causalité simple : ce qui compte est la séquence — quand protéger, quoi, pendant combien de temps — ainsi que la taille du marché intérieur et le niveau de développement initial.",
  'po': "Dans le chapitre, cette analyse joue un rôle d'arbitrage entre les deux positions exposées précédemment et empêche de conclure le débat par un slogan. Elle introduit une exigence méthodologique précieuse : une relation économique peut être réelle sans être générale, et son sens peut dépendre du contexte.",
  'co': "Paul Bairoch montre que l'histoire économique ne valide aucune relation simple entre régime commercial et développement : les grandes puissances se sont industrialisées derrière des tarifs élevés, mais d'autres pays protégés ont stagné, de sorte que la séquence et le contexte importent plus que le principe.",
 },
 'Institutions et trajectoires de développement': {
  'af': "Acemoglu soutient que les blocages du développement sont d'abord politiques : des institutions extractives permettent à une élite de capter une rente et la dissuadent d'ouvrir l'économie à l'innovation. La thèse explique une observation déconcertante, à savoir que des réformes techniquement justes échouent régulièrement. La raison en est qu'elles menacent la rente de ceux-là mêmes qui détiennent le pouvoir de les appliquer : une élite préfère un gâteau plus petit dont elle contrôle une grande part à un gâteau plus grand qu'elle ne contrôlerait plus. La contrainte n'est donc ni un manque de savoir ni un manque de capital mais un équilibre politique, ce qui explique à la fois la persistance des trajectoires et le faible effet des transferts de ressources lorsque les institutions demeurent inchangées. Acemoglu déplace ainsi la question du développement de l'économie vers l'économie politique.",
  'po': "Dans le chapitre, cette thèse propose une troisième explication du sous-développement, distincte du retard de Rostow et de la domination externe des structuralistes : le blocage est interne et politique. Elle permet de comprendre pourquoi l'aide au développement produit des résultats aussi variables selon les pays bénéficiaires.",
  'co': "Daron Acemoglu impute le sous-développement à des institutions extractives : l'élite au pouvoir n'a pas intérêt à des réformes qui menaceraient sa rente, de sorte que le blocage relève d'un équilibre politique que les seuls transferts de ressources ne modifient pas.",
 },
 'Moments critiques et bifurcation des trajectoires': {
  'af': "Robinson soutient que les écarts de développement se forment lors de moments critiques, où de petites différences institutionnelles préexistantes conduisent des sociétés comparables à bifurquer durablement. La thèse introduit la contingence dans l'analyse institutionnelle : les institutions ne sont pas choisies en fonction de leur efficacité mais résultent de conflits politiques dont l'issue dépend de rapports de force particuliers. Un choc exogène — une épidémie, une découverte, une ouverture commerciale, une colonisation — rencontre des configurations politiques initialement proches et produit des effets opposés selon l'équilibre de pouvoir qui prévalait. La bifurcation s'auto-entretient ensuite, puisque chaque type d'institution élargit la coalition qui a intérêt à le maintenir. Il en résulte des écarts qui se creusent sur des siècles sans que la géographie ni la culture ne diffèrent.",
  'po': "Dans le chapitre, cette analyse explique la persistance des écarts de développement que les modèles de convergence ne rendent pas, et elle historicise l'explication institutionnelle : les institutions ne sont pas une variable que l'on choisirait, elles sont un héritage. Elle nuance ainsi l'optimisme réformateur sans verser dans le déterminisme.",
  'co': "James Robinson montre que les trajectoires de développement bifurquent lors de moments critiques : un même choc produit des institutions opposées selon l'équilibre politique préexistant, et chaque configuration se reproduit ensuite en élargissant la coalition qui y a intérêt.",
 },
 'Dividende démographique comme opportunité conditionnelle': {
  'af': "Bloom soutient que la transition démographique ouvre une fenêtre pendant laquelle la part de la population en âge de travailler est exceptionnellement élevée, mais que ce dividende n'est qu'une opportunité, qui ne se réalise qu'à certaines conditions. Le mécanisme est le suivant : la baisse de la fécondité réduit d'abord la part des jeunes dépendants, avant que le vieillissement n'accroisse celle des personnes âgées. Pendant cette phase intermédiaire, le rapport entre actifs et inactifs est favorable, de sorte que le revenu par tête peut s'élever par le seul effet de structure, et que l'épargne nationale augmente puisqu'une moindre part des revenus est consacrée aux enfants. Bloom insiste sur le caractère conditionnel du gain : il faut que les actifs trouvent des emplois, qu'ils soient formés, et que l'épargne dégagée trouve à s'investir. À défaut, la fenêtre se referme sur un chômage de masse des jeunes.",
  'po': "Dans le chapitre, cette analyse relie la démographie au développement en évitant deux erreurs symétriques : considérer la croissance démographique comme un obstacle, à la manière de Malthus, ou comme un atout automatique. Elle introduit la notion d'opportunité conditionnelle, qui impose d'examiner les politiques d'éducation et d'emploi.",
  'co': "David Bloom montre que la transition démographique ouvre un dividende : la part des actifs y est exceptionnellement élevée et l'épargne s'accroît, mais ce gain reste conditionnel à la capacité du pays à former et à employer ces actifs avant que la fenêtre ne se referme.",
 },
 'Conditions de transformation du dividende en croissance': {
  'af': "Canning soutient que la fenêtre démographique ne produit de croissance que si les politiques de santé, d'éducation et d'emploi l'accompagnent, et que son effet mécanique est nul. La thèse détaille une chaîne de conditions dont chaque maillon est nécessaire. Une cohorte nombreuse ne devient productive que si elle est en bonne santé et formée ; elle ne génère une épargne investie que si le système financier la capte et l'alloue efficacement ; et le gain n'est durable que si la productivité progresse avant la fermeture de la fenêtre, faute de quoi le pays vieillit sans s'être enrichi. Canning souligne la conséquence du maillon manquant : une population jeune sans emploi ni formation ne constitue pas un atout différé mais une source d'instabilité immédiate. Le dividende démographique n'est donc pas un mécanisme économique mais un problème de politique publique.",
  'po': "Dans le chapitre, cette analyse complète celle de Bloom en précisant les politiques requises, et relie la démographie au capital humain étudié dans le chapitre sur la croissance. Elle permet de conclure avec nuance les sujets démographiques : la démographie est une condition, jamais une cause suffisante.",
  'co': "David Canning insiste sur le caractère conditionnel du dividende démographique : une cohorte nombreuse ne devient productive que si la santé, l'éducation et l'emploi suivent, faute de quoi la fenêtre se referme sur un chômage des jeunes porteur d'instabilité.",
 },
 'Transition démographique': {
  'af': "Landry soutient que le passage d'un régime démographique à forte mortalité et forte natalité à un régime à faible mortalité et faible natalité constitue une révolution démographique, dont le décalage entre les deux baisses engendre une forte croissance de la population. La thèse décrit une séquence en trois phases. Dans la première, mortalité et natalité sont toutes deux élevées et la population croît peu. Dans la deuxième, la mortalité recule sous l'effet de l'amélioration de l'alimentation, de l'hygiène et de la médecine, tandis que la natalité, régie par des normes sociales qui évoluent plus lentement, reste élevée : l'écart entre naissances et décès provoque une explosion démographique. Dans la troisième, la natalité baisse à son tour avec l'urbanisation, la scolarisation des filles et le coût croissant de l'enfant, et le régime se referme. La poussée démographique est donc transitoire, ce qui invalide le raisonnement malthusien.",
  'po': "Dans le chapitre, ce modèle fournit le cadre de référence de toute analyse démographique et permet de situer les pays selon la phase qu'ils traversent. Il établit que la croissance démographique rapide des pays en développement est un phénomène de transition et non un état permanent, ce qui renverse la lecture pessimiste de Malthus.",
  'co': "Adolphe Landry décrit la transition démographique : la mortalité recule avant la natalité, ce qui engendre une phase transitoire de forte croissance de la population avant que le régime ne se referme — la poussée démographique n'est donc pas structurelle mais passagère.",
 },
 "La pression démographique stimule l'innovation agricole": {
  'af': "Boserup soutient que ce n'est pas la technique agricole qui limite la population mais la population qui détermine la technique, inversant ainsi exactement la causalité malthusienne. La thèse repose sur une observation que Malthus ne pouvait pas intégrer : les techniques intensives — rotation plus rapide, irrigation, fertilisation, outillage amélioré — sont plus productives à l'hectare mais exigent beaucoup plus de travail par unité produite. Les agriculteurs ne les adoptent donc pas spontanément, non par ignorance, mais parce qu'elles sont rationnellement désavantageuses tant que la terre est abondante relativement au travail. C'est la croissance de la population qui, en raréfiant la terre, rend l'intensification avantageuse. La population devient alors une variable explicative du progrès technique agricole, et non seulement une variable expliquée par lui.",
  'po': "Dans le chapitre, cette thèse constitue la réfutation la plus élégante du piège malthusien, parce qu'elle ne nie pas les faits invoqués par Malthus mais en renverse l'interprétation. Elle introduit en outre un raisonnement de portée générale, applicable à la transition écologique : une contrainte peut être un stimulant de l'innovation plutôt qu'un obstacle.",
  'co': "Ester Boserup inverse le raisonnement malthusien : les techniques agricoles intensives exigeant plus de travail par unité produite, elles ne sont adoptées que lorsque la pression démographique raréfie la terre — la population détermine donc la technique plutôt que l'inverse.",
 },
 'Lecture pessimiste du lien population-subsistances': {
  'af': "Appliquée au développement, la thèse malthusienne soutient que la croissance démographique rapide des pays pauvres absorbe les gains de production et empêche l'élévation du revenu par tête. Le raisonnement est d'une simplicité arithmétique redoutable : si la production croît de 2 % et la population de 2,5 %, le revenu par habitant diminue alors même que la production augmente. De cette lecture découle une prescription explicite : faire du contrôle de la fécondité un préalable au développement, ce qui a inspiré des politiques de limitation des naissances dans plusieurs pays. La thèse se heurte toutefois à deux objections majeures que le chapitre développe : la transition démographique montre que la baisse de la fécondité accompagne le développement plutôt qu'elle ne le précède, et Boserup montre que la pression démographique peut stimuler la production au lieu de la plafonner.",
  'po': "Dans le chapitre, cette thèse constitue la position pessimiste de référence sur le lien entre population et développement, exposée pour être discutée. Son intérêt pédagogique est de montrer qu'un raisonnement arithmétiquement correct peut conduire à une conclusion de politique économique erronée si l'on tient pour exogène une variable qui est en réalité endogène.",
  'co': "La lecture malthusienne du développement soutient qu'une croissance démographique supérieure à la croissance de la production abaisse le revenu par tête : elle suppose cependant la fécondité exogène, alors que la transition démographique montre qu'elle baisse avec le développement lui-même.",
 },
 'Accumulation, pauvreté et rapports de production': {
  'af': "Appliquée au développement, l'analyse marxiste soutient que la pauvreté et le sous-développement ne relèvent pas d'un retard technique mais de rapports sociaux de production : l'accumulation du capital se nourrit de l'appropriation d'un surplus produit ailleurs. La thèse souligne que l'extension du capitalisme à l'échelle mondiale ne diffuse pas uniformément la prospérité ; elle intègre des régions comme fournisseurs de matières premières et de main-d'œuvre bon marché, et le surplus qu'elles produisent est accumulé dans les économies dominantes. Le sous-développement devient alors un rapport et non un état, puisqu'il suppose un ailleurs qui s'enrichit du même mouvement. Marx fournit en outre, par l'analyse de l'accumulation primitive, un démenti à l'idée que le capital procéderait d'une épargne vertueuse : son point de départ historique est un rapport de force — dépossession, mise au travail contrainte, captation de ressources coloniales.",
  'po': "Dans le chapitre, cette analyse fournit le soubassement théorique des thèses d'Amin et d'Emmanuel et permet de comprendre leur cohérence. Elle introduit l'idée que la relation entre pays développés et pays en développement doit être analysée comme un rapport, ce qui constitue l'alternative majeure à la lecture par le retard.",
  'co': "L'analyse marxiste fait du sous-développement un rapport et non un état : l'extension du capitalisme intègre certaines régions comme fournisseurs de matières premières et de main-d'œuvre bon marché, le surplus qu'elles produisent étant accumulé dans les économies dominantes.",
 },
 'Vieillissement, demande et stagnation': {
  'af': "Appliquée à la démographie, la thèse de Hansen soutient qu'un ralentissement durable de la croissance de la population et le vieillissement de la structure par âge dépriment la demande d'investissement et peuvent installer une stagnation. Le mécanisme est double. D'une part, une population qui cesse de croître réduit les besoins de logements, d'écoles, d'équipements et d'infrastructures nouvelles : l'investissement d'extension cède la place au seul renouvellement, ce qui abaisse durablement la demande de capital. D'autre part, le vieillissement accroît l'épargne de précaution et déplace la demande vers des services peu capitalistiques. Épargne abondante et investissement faible font alors chuter le taux d'intérêt d'équilibre, parfois en dessous du niveau que la politique monétaire peut atteindre, et l'économie s'installe dans un régime de demande durablement insuffisante.",
  'po': "Dans le chapitre, cette analyse constitue le symétrique du dividende démographique : elle examine ce qui arrive à l'autre extrémité de la transition. Elle montre que la démographie agit sur la croissance par la demande et non seulement par l'offre de travail, et qu'une structure par âge défavorable peut neutraliser les instruments habituels de politique économique.",
  'co': "Alvin Hansen relie le vieillissement à la stagnation séculaire : une population qui cesse de croître réduit les besoins d'investissement d'extension tandis que l'épargne demeure abondante, ce qui abaisse le taux d'intérêt d'équilibre et installe un régime durable de demande insuffisante.",
 },
 'Tragédie des communs et ressources mondiales': {
  'af': "Appliquée aux ressources globales — climat, océans, forêts —, la logique de Hardin prédit la surexploitation, parce que aucun pays n'a intérêt à se restreindre unilatéralement. La thèse transpose le mécanisme à l'échelle internationale, où il devient encore plus contraignant. Le climat est un bien commun mondial sans propriétaire ni autorité capable de contraindre. Un pays qui réduit ses émissions supporte seul la totalité du coût de l'effort et ne capte qu'une fraction infime du bénéfice, partagé entre tous. La coopération est collectivement optimale, la défection individuellement rationnelle, et l'absence d'instance de sanction rend les engagements fragiles : chacun gagne à promettre et à sous-exécuter. On comprend ainsi pourquoi les négociations climatiques achoppent moins sur le diagnostic scientifique que sur la structure même des incitations.",
  'po': "Dans le chapitre, cette transposition fait le lien entre l'analyse microéconomique des défaillances et la question de la soutenabilité globale. Elle explique la difficulté structurelle de la gouvernance climatique et justifie l'examen des dispositifs internationaux, dont elle permet d'évaluer la crédibilité à l'aune de leur capacité de sanction.",
  'co': "Transposée aux ressources mondiales, la tragédie des communs explique la difficulté des négociations climatiques : un pays qui réduit ses émissions en supporte seul le coût et n'en capte qu'une part infime du bénéfice, de sorte que la défection reste individuellement rationnelle en l'absence de sanction.",
 },
 'Gouvernance polycentrique des biens communs environnementaux': {
  'af': "Ostrom soutient que la gestion durable des ressources communes n'exige ni un marché mondial ni un gouvernement mondial, mais peut émerger de dispositifs emboîtés à plusieurs échelles, dotés de règles élaborées par les usagers eux-mêmes. La thèse oppose à la solution unique une architecture polycentrique : des règles définies au plus près de la ressource, par ceux qui l'utilisent et peuvent se surveiller mutuellement, articulées à des niveaux supérieurs qui arbitrent les conflits et garantissent le droit de s'organiser. L'efficacité de ce dispositif tient à deux propriétés qu'une règle mondiale uniforme ne possède pas : l'adaptation aux conditions locales, qui rend la règle pertinente, et l'observabilité réciproque, qui rend son respect vérifiable à faible coût. Ostrom ne nie donc pas le problème posé par Hardin ; elle montre que la structure institutionnelle qu'il suppose — le libre accès intégral — est rare dans les faits.",
  'po': "Dans le chapitre, cette analyse fournit le dépassement attendu de l'opposition entre marché et État dans la gestion environnementale, et montre que la soutenabilité est d'abord une question institutionnelle. Elle permet de conclure les sujets sur les communs autrement que par un constat d'impuissance.",
  'co': "Elinor Ostrom oppose à la solution unique une gouvernance polycentrique des communs : des règles élaborées localement par les usagers, articulées à des niveaux supérieurs, combinent adaptation aux conditions locales et observabilité réciproque, ce qu'aucune règle mondiale uniforme ne permet.",
 },
 'Définition du développement durable': {
  'af': "Le rapport Brundtland définit le développement durable comme celui qui répond aux besoins du présent sans compromettre la capacité des générations futures à répondre aux leurs. La formule articule deux exigences qui peuvent entrer en tension, et c'est précisément ce qui en fait un bon point de départ de problématique. L'exigence intragénérationnelle impose de satisfaire les besoins essentiels du présent, ce qui suppose du développement et non son arrêt : le rapport insiste sur la pauvreté comme cause de dégradation environnementale. L'exigence intergénérationnelle impose de préserver les capacités productives et les écosystèmes. De cette définition découlent le découpage canonique en trois piliers — économique, social, environnemental — et le débat entre soutenabilité faible, qui admet la substitution du capital naturel par du capital technique, et soutenabilité forte, qui la refuse pour les ressources critiques.",
  'po': "Dans le chapitre, cette définition fournit le cadre conceptuel de la partie consacrée à la soutenabilité et le vocabulaire commun des négociations internationales. Sa tension interne est son principal intérêt analytique : elle montre que développement et préservation ne sont pas spontanément compatibles et qu'il faut en examiner les arbitrages.",
  'co': "Selon la définition du rapport Brundtland (1987), le développement durable répond aux besoins du présent sans compromettre la capacité des générations futures à répondre aux leurs : cette formule articule une exigence intragénérationnelle et une exigence intergénérationnelle qui peuvent entrer en tension.",
 },
 'Automatisation, tâches et polarisation': {
  'af': "Autor soutient que l'automatisation ne remplace pas des métiers mais des tâches, et que cette distinction commande entièrement son effet sur l'emploi. La thèse repose sur un critère précis : une tâche est automatisable si elle peut être décrite par des règles explicites, c'est-à-dire si elle est routinière. Or les tâches routinières sont concentrées au milieu de la distribution des salaires — comptabilité d'exécution, guichet, opérations d'usine répétitives. Les tâches non routinières manuelles, qui exigent dextérité et adaptation au contexte, résistent : soins, nettoyage, restauration, livraison. Les tâches non routinières abstraites, qui exigent conception et jugement, résistent également et se trouvent même valorisées, la machine les complétant au lieu de les remplacer. Il en résulte une polarisation : l'emploi intermédiaire se creuse tandis que les deux extrémités de l'échelle se gonflent.",
  'po': "Dans le chapitre, cette analyse relie le progrès technique aux inégalités et montre que le déversement décrit par Sauvy, s'il existe, ne garantit pas la qualité des emplois de destination. Elle fournit l'outil permettant d'analyser rigoureusement l'effet de l'intelligence artificielle, puisqu'elle oblige à raisonner en tâches plutôt qu'en professions.",
  'co': "David Autor montre que l'automatisation remplace des tâches et non des métiers : les tâches routinières étant concentrées au milieu de l'échelle salariale, leur disparition polarise l'emploi entre des tâches manuelles non routinières et des tâches abstraites que la machine complète.",
 },
}
